export function makeWorkflowRunsPage(
  items: readonly WorkflowRunSummary[] = [sampleWorkflowRun, sampleWorkflowRunCompleted],
): PaginatedResponse<WorkflowRunSummary> {
  return {
    ok: true,
    items: [...items],
    pagination: {
      page: 1,
      pageSize: 50,
      total: items.length,
      pages: 1,
    },
    sort: { field: "started_at", dir: "desc" },
    filter: { status: "all" },
  };
}

